import * as http from 'node:http';
import * as net from 'node:net';
async function main(): Promise<void> {
  const s = net.createServer((sock: any) => { sock.on('data', () => {}); });
  await new Promise<void>((r) => s.listen(0, '127.0.0.1', () => r()));
  const port = (s.address() as any).port;
  await new Promise<void>((resolve) => {
    const req: any = (http as any).request({ host: '127.0.0.1', port, agent: false });
    req.setTimeout(50, () => { console.log('timeout fired'); req.destroy(); });
    req.on('error', () => {}); req.on('close', () => { console.log('closed'); resolve(); });
    req.end();
  });
  const a: any = new (http as any).Agent({ keepAlive: true, maxSockets: 2, maxFreeSockets: 3, timeout: 50, scheduling: 'fifo' });
  console.log(a.maxSockets, a.maxFreeSockets, a.keepAlive, a.options.timeout, a.scheduling, a.defaultPort, a.protocol);
  s.close();

}
